-- CPF_LOGICAL_DATABASE=cpfDB
UPDATE OPS_RUNTIME_INSTANCE_STATE SET runtime_role='CENTER_CUT' WHERE runtime_role='CENTER_CUT_RUNNER';
UPDATE BAT_RUNTIME_INSTANCE SET runtime_role='CENTER_CUT' WHERE runtime_role='CENTER_CUT_RUNNER';
UPDATE BAT_DEPLOYMENT_CELL SET runtime_role='CENTER_CUT' WHERE runtime_role='CENTER_CUT_RUNNER';
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE DROP CONSTRAINT ck_ops_runtime_instance_role;
ALTER TABLE BAT_RUNTIME_INSTANCE DROP CONSTRAINT ck_bat_runtime_instance_role;
ALTER TABLE BAT_DEPLOYMENT_CELL DROP CONSTRAINT ck_bat_deployment_runtime_role;
ALTER TABLE OPS_RUNTIME_INSTANCE_STATE ADD CONSTRAINT ck_ops_runtime_instance_role CHECK (runtime_role IS NULL OR runtime_role IN ('APPLICATION','CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT','AGENT'));
ALTER TABLE BAT_RUNTIME_INSTANCE ADD CONSTRAINT ck_bat_runtime_instance_role CHECK (runtime_role IN ('CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT','AGENT'));
ALTER TABLE BAT_DEPLOYMENT_CELL ADD CONSTRAINT ck_bat_deployment_runtime_role CHECK (runtime_role IN ('CONTROL_PLANE','SCHEDULER','WORKER','CENTER_CUT','AGENT'));
